import concurrent.futures, subprocess, time, math
rows=[line.rstrip('\\n').split('\\t') for line in open('work/bigwig_jobs.tsv')]

def run(fields):
    exp,bwacc,url,biosample=fields[0],fields[1],fields[2],fields[3] if len(fields)>3 else ''
    try:
        cp=subprocess.run(['python3','work/score_one_bigwig.py',exp,bwacc,url,biosample],text=True,capture_output=True,timeout=18)
        if cp.returncode==0 and cp.stdout.strip():
            return cp.stdout.strip()+'\\tok'
        return f'nan\\t{exp}\\t{bwacc}\\t{biosample}\\tERR:{cp.stderr[-80:].replace(chr(9),\" \").replace(chr(10),\" \")}'
    except subprocess.TimeoutExpired:
        return f'nan\\t{exp}\\t{bwacc}\\t{biosample}\\tTIMEOUT'
start=time.time(); out=[]; done=0
with concurrent.futures.ThreadPoolExecutor(max_workers=24) as ex:
    futs=[ex.submit(run,r) for r in rows]
    for fut in concurrent.futures.as_completed(futs):
        out.append(fut.result()); done+=1
        if done%100==0: print('done',done,'elapsed',round(time.time()-start,1), flush=True)
def key(line):
    try: return float(line.split('\\t',1)[0])
    except: return float('nan')
out.sort(key=lambda l: -999 if math.isnan(key(l)) else key(l), reverse=True)
with open('work/timed_bigwig_top75_ranking.tsv','w') as f:
    f.write('rank\\tpearson\\texperiment\\tbigwig\\tbiosample\\tstatus\\n')
    for i,line in enumerate(out,1): f.write(f'{i}\\t{line}\\n')
print(open('work/timed_bigwig_top75_ranking.tsv').read()[:8000])
